CREATE TABLE invitation_schema (singleton INTEGER PRIMARY KEY CHECK(singleton=1), version INTEGER NOT NULL CHECK(version=1)) STRICT;CREATE TABLE invitation_phones (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, platform TEXT NOT NULL CHECK(platform IN ('apple','android')), secret_hash TEXT NOT NULL, token_digest TEXT NOT NULL, generation INTEGER NOT NULL CHECK(generation>0), created_at INTEGER NOT NULL, permission_granted INTEGER NOT NULL DEFAULT 0 CHECK(permission_granted IN (0,1)), resident_active INTEGER NOT NULL DEFAULT 0 CHECK(resident_active IN (0,1))) STRICT;CREATE INDEX invitation_phones_user ON invitation_phones(user_id,id);CREATE TABLE invitation_consents (id TEXT PRIMARY KEY, phone_id TEXT NOT NULL REFERENCES invitation_phones(id) ON DELETE CASCADE, receiver_id TEXT NOT NULL REFERENCES remote_receivers(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, grant_id TEXT, grant_hash TEXT, enabled INTEGER NOT NULL CHECK(enabled IN (0,1)), transport TEXT NOT NULL CHECK(transport IN ('apns','fcm','android_resident')), generation INTEGER NOT NULL CHECK(generation>0), transport_generation INTEGER NOT NULL DEFAULT 0 CHECK(transport_generation>=0), broker_enrollment TEXT, broker_ticket TEXT, transport_status TEXT NOT NULL DEFAULT 'unavailable', UNIQUE(phone_id,receiver_id)) STRICT;CREATE INDEX invitation_consents_user ON invitation_consents(user_id,id);CREATE TABLE invitation_events (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, enrollment_id TEXT NOT NULL REFERENCES invitation_consents(id) ON DELETE CASCADE, phone_id TEXT NOT NULL REFERENCES invitation_phones(id) ON DELETE CASCADE, receiver_id TEXT NOT NULL REFERENCES remote_receivers(id) ON DELETE CASCADE, foreground_id TEXT NOT NULL, grant_id TEXT NOT NULL, phone_generation INTEGER NOT NULL, consent_generation INTEGER NOT NULL, transport_generation INTEGER NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, phase TEXT NOT NULL CHECK(phase IN ('admitted','attempted','cancelled')), outcome TEXT, UNIQUE(receiver_id,foreground_id,enrollment_id)) STRICT;CREATE INDEX invitation_events_user ON invitation_events(user_id,id);CREATE INDEX invitation_events_pending ON invitation_events(phase,expires_at,id);CREATE TABLE invitation_cooldowns (receiver_id TEXT NOT NULL REFERENCES remote_receivers(id) ON DELETE CASCADE, phone_id TEXT NOT NULL REFERENCES invitation_phones(id) ON DELETE CASCADE, last_admitted_at INTEGER NOT NULL, PRIMARY KEY(receiver_id,phone_id)) STRICT;CREATE TABLE invitation_broker_revocations (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, enrollment_id TEXT NOT NULL, generation INTEGER NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0) STRICT;INSERT INTO invitation_schema VALUES(1,1);